/* eslint-disable @stencil-community/required-jsdoc */
import { Component, h, Prop, Element, Host, State } from '@stencil/core';
import { Status } from '@src/shared/base-props';
import { TimezoneInfo } from '@src/shared/timezone';
import { Dayjs } from 'dayjs';
import { globalConfigStore } from '@src/shared/stores';
import { DateTimeFormatOptions, NormalizedDatePickerComparisonProps } from '../../types';
import { SvgComparison } from './SvgComparison';
import { getComparisonPresetValue } from '../presets/utils';
import { dateMessages, datePickerMessages } from '@fe-infra/keystone-locales';
import { t } from '@src/shared/i18n';
import { KsIconHelp } from '@fe-infra/keystone-icons-stencil';

const NOOP = () => undefined;
const DISABLED_COMPARISON: NormalizedDatePickerComparisonProps = {
  active: false,
  switchable: false,
  switchDisabled: false,
  switchDisabledTooltip: undefined,
  value: [null, null],
};

const prefix = 'date-comparison';

@Component({
  tag: 'ks-date-time-picker-comparison',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsDateTimePickerComparison {
  @Element() el!: HTMLKsDateTimePickerComparisonElement;
  /** The current values to display in the input field(s). */
  @Prop() value!: [Dayjs | null, Dayjs | null];
  /** If true, the presenter will display two input fields for a range. If false, a single input field is displayed. */
  @Prop() isRange = false;
  /** Placeholder text for the input field when `isRange` is false and no value is present. */
  @Prop() placeholder!: [string | undefined, string | undefined];
  /** If true, the input field(s) will be disabled and non-interactive. */
  @Prop() disabled!: [boolean, boolean];
  /** If true, enable the comparison mode. */
  @Prop() comparison!: NormalizedDatePickerComparisonProps;
  /** If true, a clear button is shown when the input has a value and is focused, allowing the user to clear the content. */
  @Prop() clearable!: boolean;
  /** Sets the validation status of the input, affecting its visual style (e.g., 'error', 'warning'). */
  @Prop() status!: Status;
  /** The timezone info */ // TODO label 应当允许完全自定义的节点
  @Prop() timezone!: TimezoneInfo;
  /** Whether or not to show the timezone indicator. */
  @Prop() showTimezone!: false | { placement: 'input' | 'panel'; style?: 'longOffset' | 'full' }; // TODO label 应当允许完全自定义的节点
  @Prop() open!: boolean;

  @Prop() setComparison!: (comparison: NormalizedDatePickerComparisonProps) => void;
  @Prop() isSelectingComparisonValue!: boolean;
  @Prop() setIsSelectingComparisonValue!: (v: boolean) => void;
  @Prop() setViewDate!: (viewDate: Dayjs) => void;

  @Prop() displayFormatOptions!: DateTimeFormatOptions;
  @Prop() hoverPart!: 'start' | 'end' | null;

  @State() isFocused = false;

  get locale() {
    return globalConfigStore.state.locale;
  }

  private handleSwitchActive = (event: CustomEvent<boolean>) => {
    const checked = event.detail;
    if (checked) {
      this.setComparison({
        ...this.comparison,
        active: checked,
        value:
          this.comparison.defaultPreset && !this.comparison.value[0] && !this.comparison.value[1]
            ? getComparisonPresetValue(this.value, this.comparison.defaultPreset)
            : this.comparison.value,
      });
      setTimeout(() => {
        if (this.comparison.active) {
          this.setIsSelectingComparisonValue(true);
          this.comparison.value[0] && this.setViewDate(this.comparison.value[0]);
        }
      }, 100); // FIXME cross React/Vue - Stencil controlled state management is very bad
    } else {
      this.setComparison({ ...this.comparison, active: checked, value: [null, null] });
      this.setIsSelectingComparisonValue(false);
    }
  };
  private handleClickValue = () => {
    if (this.isSelectingComparisonValue) {
      this.setIsSelectingComparisonValue(false);
      this.value[0] && this.setViewDate(this.value[0]);
    }
  };
  private handleClickComparisonValue = () => {
    if (!this.isSelectingComparisonValue) {
      this.setIsSelectingComparisonValue(true);
      this.comparison.value[0] && this.setViewDate(this.comparison.value[0]);
    }
  };

  disconnectedCallback() {
    this.setIsSelectingComparisonValue(false);
  }

  render() {
    if (!this.comparison.active && !this.comparison.switchable) {
      return <Host></Host>;
    }

    const displayFieldProps = {
      isRange: this.isRange,
      placeholder: this.placeholder,
      disabled: this.disabled,
      comparison: DISABLED_COMPARISON,
      clearable: false,
      status: 'default',
      timezone: this.timezone,
      showTimezone: false,
      open: this.open,
      forceActive: false,
      displayFormatOptions: this.displayFormatOptions,
      handleClear: NOOP,
    } satisfies Partial<HTMLKsDateTimePickerDisplayFieldElement>;

    return (
      <Host>
        <div class={prefix}>
          <div class={`${prefix}__header`}>
            <div class={`${prefix}__header-title`}>{t(dateMessages.pickerTitle)}</div>
            <div class={`${prefix}__header-switch`}>
              <ks-tooltip
                content={this.comparison.switchDisabledTooltip}
                disabled={!this.comparison.switchDisabled || !this.comparison.switchDisabledTooltip}
                placement="right"
                size="sm"
              >
                <ks-switch
                  size="md"
                  labelPosition="start"
                  checked={this.comparison.active}
                  disabled={Boolean(this.comparison.switchDisabled)}
                  onKsChange={this.handleSwitchActive}
                  data-testid="comparison-index-tBHveN"
                >
                  <div class={`${prefix}__header-switch-label`}>
                    {t(datePickerMessages.compare)}
                    <ks-tooltip content={t(datePickerMessages.compareHelp)}>
                      <KsIconHelp size={14} color="var(--ks-color-neutral-lowOnSurface)" />
                    </ks-tooltip>
                  </div>
                </ks-switch>
              </ks-tooltip>
            </div>
          </div>

          {this.comparison.active && (
            <div class={`${prefix}__selections`}>
              <div>
                <div class={`${prefix}__selections-label`}>{t(dateMessages.pickerCurrentDate)}</div>
                <ks-date-time-picker-display-field
                  exportparts="fieldTimezone"
                  {...displayFieldProps}
                  class={`${prefix}__selections-display-field`}
                  forceActive={!this.isSelectingComparisonValue}
                  value={this.value}
                  hoverPart={this.isSelectingComparisonValue ? null : this.hoverPart}
                  onClick={this.handleClickValue}
                  data-testid="comparison-index-9zH1Xd"
                />
              </div>
              <SvgComparison className={`${prefix}__selections-icon-comparison`} />
              <div>
                <div class={`${prefix}__selections-label`}>{t(dateMessages.pickerCompareDate)}</div>
                <ks-date-time-picker-display-field
                  exportparts="fieldTimezone"
                  {...displayFieldProps}
                  class={`${prefix}__selections-display-field`}
                  forceActive={this.isSelectingComparisonValue}
                  value={this.comparison.value}
                  hoverPart={this.isSelectingComparisonValue ? this.hoverPart : null}
                  onClick={this.handleClickComparisonValue}
                  data-testid="comparison-index-5hDpCL"
                />
              </div>
            </div>
          )}
        </div>
      </Host>
    );
  }
}
